//! Unverified controlled smoothing diagnostic; all configuration explicitly supplied.
use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_paired_topology_v1::build,creature_skin_smoothing_v1::smooth,native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),4);let b=fs::read(&a[1]).unwrap();let n=fs::read(&a[2]).unwrap();let r=fs::read(&a[3]).unwrap();assert_eq!(b.len(),1008);assert_eq!(n.len(),1552);assert_eq!(r.len(),880);let idx:Vec<_>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();let normals:Vec<[f32;3]>=n[..528].chunks_exact(12).map(|x|std::array::from_fn(|i|f32::from_le_bytes(x[i*4..i*4+4].try_into().unwrap()))).collect();let records:Vec<[u8;20]>=r.chunks_exact(20).map(|x|x.try_into().unwrap()).collect();let top=build(&idx,44).unwrap();let destination=vec![[0u8;20];44];let mut out=Vec::new();for count in [0,1,2]{for record in smooth(&records,&destination,&normals,&idx,&top,count,0.5,Policy::Mxcsr1f80).unwrap(){out.extend(record)}}io::stdout().write_all(&out).unwrap()}
